// Package postgres is Forge's PostgreSQL adapter: a configured pgx connection
// pool, explicit transactions, error translation into fault errors, advisory
// locks and SQL-file migrations.
//
// Forge is SQL-first. Repositories hold explicit SQL (hand-written or
// generated by sqlc, whose pgx/v5 DBTX interface matches DBTX here); there is
// no ORM and no query builder.
package postgres

import (
	"context"
	"errors"
	"fmt"
	"net/url"
	"strconv"
	"time"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgconn"
	"github.com/jackc/pgx/v5/pgtype"
	"github.com/jackc/pgx/v5/pgxpool"

	"github.com/rocketinsidecorp/forge-go/config"
	"github.com/rocketinsidecorp/forge-go/internal/pgurl"
	"github.com/rocketinsidecorp/forge-go/sqldb"
)

// DBTX is satisfied by *DB and pgx.Tx, so a repository written against it runs
// both standalone and inside a transaction.
type DBTX interface {
	Exec(ctx context.Context, sql string, arguments ...any) (pgconn.CommandTag, error)
	Query(ctx context.Context, sql string, args ...any) (pgx.Rows, error)
	QueryRow(ctx context.Context, sql string, args ...any) pgx.Row
}

// DB is a PostgreSQL connection pool.
type DB struct {
	pool *pgxpool.Pool
	// unobserve stops the pool metrics; nil without telemetry.
	unobserve func()
}

var _ DBTX = (*DB)(nil)

// Open creates a connection pool from validated configuration and verifies
// connectivity within cfg.ConnectTimeout, so misconfiguration fails at
// startup rather than on the first request.
//
// Outside development and test (cfg.Environment, which config.Load and
// forge.New set from FORGE_ENV) it also refuses, with ErrRowSecurityBypass,
// a role that could bypass row-level security; see RequireRowSecurity for
// the rules and AllowRowSecurityBypass for the explicit opt-out. With
// Lazy(true) it connects on the first query instead.
func Open(ctx context.Context, cfg config.Database, opts ...Option) (*DB, error) {
	var settings openOptions
	for _, option := range opts {
		if option != nil {
			option(&settings)
		}
	}
	checkRowSecurity := cfg.Environment != config.Development && cfg.Environment != config.Test
	if settings.rowSecurity != nil {
		checkRowSecurity = *settings.rowSecurity
	}
	observer, err := sqldb.NewObserver(settings.telemetry, poolSystem, classify)
	if err != nil {
		return nil, err
	}
	// The serving pool takes no session setting from the environment: a
	// PGOPTIONS='-c forge.tenant_id=...' would give every pooled session a
	// default tenant, so a query outside InTenantTx would read that
	// tenant's rows instead of none.
	poolConfig, err := parseConfig(cfg, stripEnvironmentSession)
	if err != nil {
		return nil, err
	}
	if observer != nil {
		poolConfig.ConnConfig.Tracer = &queryTracer{observer: observer}
	}
	poolConfig.MaxConns = cfg.MaxConns
	poolConfig.MinConns = cfg.MinConns
	poolConfig.MaxConnLifetime = cfg.MaxConnLifetime
	poolConfig.MaxConnIdleTime = cfg.MaxConnIdleTime
	poolConfig.ConnConfig.RuntimeParams["statement_timeout"] = strconv.FormatInt(cfg.StatementTimeout.Milliseconds(), 10)
	if poolConfig.ConnConfig.RuntimeParams["application_name"] == "" {
		poolConfig.ConnConfig.RuntimeParams["application_name"] = "forge"
	}
	// pgx scans timestamptz into time.Local by default, which makes results
	// depend on the host's zone. Forge returns instants in UTC everywhere.
	poolConfig.AfterConnect = func(ctx context.Context, conn *pgx.Conn) error {
		conn.TypeMap().RegisterType(&pgtype.Type{
			Name:  "timestamptz",
			OID:   pgtype.TimestamptzOID,
			Codec: &pgtype.TimestamptzCodec{ScanLocation: time.UTC},
		})
		if settings.lazy && checkRowSecurity {
			// Nothing was checked when the pool was created: every
			// connection is, before its first use.
			return refuseRowSecurityBypass(ctx, conn)
		}
		return nil
	}
	if settings.lazy {
		poolConfig.MinConns = 0
	}

	pool, err := pgxpool.NewWithConfig(ctx, poolConfig)
	if err != nil {
		return nil, fmt.Errorf("create connection pool: %w", err)
	}
	if !settings.lazy {
		pingCtx, cancel := context.WithTimeout(ctx, cfg.ConnectTimeout)
		defer cancel()
		if err := pool.Ping(pingCtx); err != nil {
			pool.Close()
			return nil, fmt.Errorf("connect to database: %w", err)
		}
		if checkRowSecurity {
			if err := refuseRowSecurityBypass(pingCtx, pool); err != nil {
				pool.Close()
				return nil, err
			}
		}
	}
	unobserve, err := observePool(settings.telemetry, settings.poolName, pool)
	if err != nil {
		pool.Close()
		return nil, err
	}
	return &DB{pool: pool, unobserve: unobserve}, nil
}

// sessionSource says whether the session settings pgx reads from the
// environment (PGOPTIONS, PGTZ, PGAPPNAME) reach the connection.
type sessionSource bool

const (
	// stripEnvironmentSession keeps only the session settings the URL
	// names: the serving pool's choice.
	stripEnvironmentSession sessionSource = false
	// keepEnvironmentSession lets the environment fill the session settings
	// the URL leaves out, as for psql: the migrator's choice, so an operator
	// can run PGOPTIONS='-c lock_timeout=5s' forge migrate.
	keepEnvironmentSession sessionSource = true
)

// parseConfig builds the pgx configuration shared by the pool and the
// migrator's dedicated session.
func parseConfig(cfg config.Database, session sessionSource) (*pgxpool.Config, error) {
	if cfg.URL.IsZero() {
		return nil, errors.New("database is not configured: set FORGE_DATABASE_URL")
	}
	if adapter := cfg.Adapter(); adapter != config.AdapterPostgres {
		return nil, fmt.Errorf("FORGE_DATABASE_URL selects the %s adapter, but this application uses postgres", adapter)
	}
	// PG* variables fill what the URL leaves out, but TLS (sslmode, the
	// certificate files, channel binding, required authentication) is the
	// URL's alone: a PGSSLMODE in the process environment must not weaken or
	// redirect it, and a PGSSLROOTCERT the URL does not repeat is refused,
	// not ignored. See pgurl.Isolate.
	iso, err := pgurl.Isolate(cfg.URL.Reveal(), pgurl.TLSOnly, nil)
	if err != nil {
		var refused *pgurl.RefusedError
		if errors.As(err, &refused) {
			// Names variables and parameters, never a value or the URL.
			return nil, refused
		}
		return nil, errors.New("FORGE_DATABASE_URL is not a valid PostgreSQL connection string")
	}
	defer iso.Close()
	poolConfig, err := pgxpool.ParseConfig(iso.URL)
	if err != nil {
		// Not wrapped: parse errors can quote the connection string.
		return nil, errors.New("FORGE_DATABASE_URL is not a valid PostgreSQL connection string")
	}
	if err := matchesValidatedURL(cfg.URL.Reveal(), poolConfig.ConnConfig.Config); err != nil {
		return nil, err
	}
	if session == stripEnvironmentSession {
		iso.StripSession(poolConfig.ConnConfig.RuntimeParams)
	}
	poolConfig.ConnConfig.ConnectTimeout = cfg.ConnectTimeout
	return poolConfig, nil
}

// matchesValidatedURL checks that pgx, whose libpq-style parser differs from
// net/url, will connect exactly where and how config validated: the same
// host and port, and TLS on every attempt (pgx implements sslmode=prefer and
// allow as plaintext fallbacks) whenever the URL asks for an encrypted mode.
// It is defense in depth behind config's rejection of ambiguous URLs.
func matchesValidatedURL(raw string, parsed pgconn.Config) error {
	validated, err := url.Parse(raw)
	if err != nil {
		return errors.New("FORGE_DATABASE_URL is not a valid PostgreSQL connection string")
	}
	port := uint16(5432)
	if validated.Port() != "" {
		value, err := strconv.ParseUint(validated.Port(), 10, 16)
		if err != nil {
			return errors.New("FORGE_DATABASE_URL has an invalid port")
		}
		port = uint16(value)
	}
	ambiguous := errors.New("FORGE_DATABASE_URL is ambiguous: PostgreSQL would connect differently than it was validated")
	attempts := append([]*pgconn.FallbackConfig{{Host: parsed.Host, Port: parsed.Port, TLSConfig: parsed.TLSConfig}}, parsed.Fallbacks...)
	encrypted := map[string]bool{"require": true, "verify-ca": true, "verify-full": true}[validated.Query().Get("sslmode")]
	for _, attempt := range attempts {
		if attempt.Host != validated.Hostname() || attempt.Port != port || (encrypted && attempt.TLSConfig == nil) {
			return ambiguous
		}
	}
	return nil
}

// Exec runs a statement without returning rows, on the pool.
func (db *DB) Exec(ctx context.Context, sql string, arguments ...any) (pgconn.CommandTag, error) {
	return db.pool.Exec(ctx, sql, arguments...)
}

// Query runs a query that returns rows, on the pool. The caller must close the rows.
func (db *DB) Query(ctx context.Context, sql string, args ...any) (pgx.Rows, error) {
	return db.pool.Query(ctx, sql, args...)
}

// QueryRow runs a query that returns at most one row, on the pool.
func (db *DB) QueryRow(ctx context.Context, sql string, args ...any) pgx.Row {
	return db.pool.QueryRow(ctx, sql, args...)
}

// Ping verifies a connection can be used. Its signature matches health.Check,
// so it can be registered directly as a readiness check.
func (db *DB) Ping(ctx context.Context) error { return db.pool.Ping(ctx) }

// Close waits for acquired connections to be released and closes the pool.
func (db *DB) Close() {
	db.stopObserving()
	db.pool.Close()
}

// Shutdown closes the pool like Close but stops waiting when ctx ends, so a
// connection held by a stuck request cannot block process exit. Its signature
// matches forge.ShutdownHook: app.OnShutdown(db.Shutdown).
func (db *DB) Shutdown(ctx context.Context) error {
	db.stopObserving()
	return sqldb.CloseWithin(ctx, func() error { db.pool.Close(); return nil }, func() int { return int(db.pool.Stat().AcquiredConns()) })
}

// stopObserving removes the pool from the connection metrics: a closed pool
// is no longer read at every collection.
func (db *DB) stopObserving() {
	if db.unobserve != nil {
		db.unobserve()
	}
}

// Pool exposes the underlying pgx pool for capabilities Forge does not wrap,
// such as COPY or LISTEN/NOTIFY. It is the explicit escape hatch.
func (db *DB) Pool() *pgxpool.Pool { return db.pool }
